#include <vector>
#include <algorithm>

using namespace std;

class Knapsack1DTemplate {
public:
    // Space-optimized 1D Array 0-1 Knapsack solution
    int solveKnapsack(const vector<int>& profits, const vector<int>& weights, int capacity) {
        int n = profits.size();
        if (capacity <= 0 || n == 0 || weights.size() != n) {
            return 0;
        }

        // DP array initialized to 0
        vector<int> dp(capacity + 1, 0);

        // Populate base case for the first item
        for (int c = 0; c <= capacity; ++c) {
            if (weights[0] <= c) {
                dp[c] = profits[0];
            }
        }

        // Process remaining items
        for (int i = 1; i < n; ++i) {
            // Traverse capacity backwards to maintain 0-1 constraint
            for (int c = capacity; c >= weights[i]; --c) {
                dp[c] = max(dp[c], profits[i] + dp[c - weights[i]]);
            }
        }

        return dp[capacity];
    }
};

